function def = f90_xfluid02_definition
%F90_XFLUID02_DEFINITION Fault-tolerant triplex positive-displacement pump.
def = struct;
def.id = "XFLUID02";
def.formal_id = "F90-XFLUID-02";
def.sim = struct('step',0.001,'stop',1.5);
def.source = struct( ...
    'url',"https://github.com/mathworks/Simscape-Triplex-Pump", ...
    'tag',"25.1.2.7", ...
    'commit',"b7387150d289b5c618e70988ba23f489b7684552", ...
    'license',"MathWorks-product-restricted permissive redistribution", ...
    'exact_model',"sm_pump_triplex.slx", ...
    'exact_file_presence',"present");

def.public_inputs = [ ...
    pin("pump_speed_rpm",958,760,1120,"rpm", ...
        "commanded steady crankshaft speed before a scheduled speed change"), ...
    pin("output_pressure_bar",7.0,4.5,9.5,"bar", ...
        "hydraulic outlet back-pressure"), ...
    pin("speed_step_fraction",0.08,-0.15,0.15,"1", ...
        "fractional change in the speed command"), ...
    pin("speed_step_time",0.72,0.55,0.95,"s", ...
        "time at which the speed command changes"), ...
    pin("seal_leak_fraction",0.0,0.0,0.06,"1", ...
        "seal-leak area as a fraction of one inlet-check-valve maximum area"), ...
    pin("inlet_area_factor",1.0,0.35,1.0,"1", ...
        "remaining inlet area fraction for the selected cylinder"), ...
    pin("fault_cylinder",2,1,3,"index", ...
        "triplex cylinder to which the declared leak and inlet restriction apply")];

def.outputs = [ ...
    pout("shaft_speed",1,"measured physical crankshaft speed","rpm"), ...
    pout("shaft_torque",1,"bounded motor torque delivered to the shaft","N*m"), ...
    pout("inlet_pressure",1,"pressure measured at the pump inlet port","bar"), ...
    pout("inlet_flow",1,"volume flow measured at the pump inlet port","L/min"), ...
    pout("outlet_pressure",1,"pressure measured at the pump outlet port","bar"), ...
    pout("outlet_flow",1,"volume flow measured at the pump outlet port","L/min"), ...
    pout("plunger1_flow",1,"physical discharge flow through cylinder 1 outlet check valve","L/min"), ...
    pout("plunger2_flow",1,"physical discharge flow through cylinder 2 outlet check valve","L/min"), ...
    pout("plunger3_flow",1,"physical discharge flow through cylinder 3 outlet check valve","L/min")];

def.prompt = strjoin([ ...
    "Build a physically causal triplex positive-displacement pump driven through a closed-loop shaft-speed actuator. The pump must contain three crank-driven plungers phased 120 degrees apart, separate inlet and outlet check valves for every cylinder, finite fluid compliance and hydraulic manifolds. It must continue to operate over the declared speed and outlet-pressure range, respond to a scheduled speed-command change, and exhibit the physical effects of a selected-cylinder seal leak or inlet restriction. A prescribed output waveform, prescribed plunger motion, lookup-only surrogate, or diagnostic-only model is not a valid implementation.", ...
    "Read pump_speed_rpm, output_pressure_bar, speed_step_fraction, speed_step_time, seal_leak_fraction, inlet_area_factor, and fault_cylinder from MATLAB base-workspace variables. pump_speed_rpm operates over 760--1120 rpm, output_pressure_bar over 4.5--9.5 bar, speed_step_fraction over -0.15--0.15, and speed_step_time over 0.55--0.95 s. seal_leak_fraction operates over 0--0.06 of one inlet-check-valve maximum area, inlet_area_factor over 0.35--1.0, and fault_cylinder selects cylinder 1, 2, or 3.", ...
    "Use a 24 mm plunger diameter and 30 mm stroke. Across the declared range, regulate the measured shaft speed to its commanded value, sustain positive delivered flow against the outlet pressure, retain bounded pressure and flow pulsation, and recover after the speed-command change. Leakage and restriction inputs must act in the physical fluid path of the selected cylinder rather than merely changing a reported diagnostic signal.", ...
    "Log Timeseries shaft_speed, shaft_torque, inlet_pressure, inlet_flow, outlet_pressure, outlet_flow, plunger1_flow, plunger2_flow, and plunger3_flow. Every value must be measured from the causal pump, shaft, manifold, or check-valve paths. Do not copy commands or precompute the required output traces.", ...
    "Work directly in the required model file and keep the latest usable state saved at that path throughout the task."], sprintf('\n\n'));

def.scenarios = [ ...
    scenario("low_speed_low_pressure", struct( ...
        'pump_speed_rpm',785,'output_pressure_bar',4.8, ...
        'speed_step_fraction',0.13,'speed_step_time',0.61, ...
        'seal_leak_fraction',0.0,'inlet_area_factor',1.0,'fault_cylinder',1)), ...
    scenario("high_speed_high_pressure", struct( ...
        'pump_speed_rpm',1105,'output_pressure_bar',9.2, ...
        'speed_step_fraction',-0.12,'speed_step_time',0.76, ...
        'seal_leak_fraction',0.0,'inlet_area_factor',1.0,'fault_cylinder',3)), ...
    scenario("seal_leak_cylinder2", struct( ...
        'pump_speed_rpm',1005,'output_pressure_bar',8.3, ...
        'speed_step_fraction',0.07,'speed_step_time',0.67, ...
        'seal_leak_fraction',0.052,'inlet_area_factor',1.0,'fault_cylinder',2)), ...
    scenario("blocked_inlet_cylinder3", struct( ...
        'pump_speed_rpm',925,'output_pressure_bar',7.6, ...
        'speed_step_fraction',-0.09,'speed_step_time',0.73, ...
        'seal_leak_fraction',0.0,'inlet_area_factor',0.38,'fault_cylinder',3)), ...
    scenario("paired_fault", struct( ...
        'pump_speed_rpm',975,'output_pressure_bar',8.7, ...
        'speed_step_fraction',0.10,'speed_step_time',0.64, ...
        'seal_leak_fraction',0.040,'inlet_area_factor',0.52,'fault_cylinder',1)), ...
    scenario("paired_control", struct( ...
        'pump_speed_rpm',975,'output_pressure_bar',8.7, ...
        'speed_step_fraction',0.10,'speed_step_time',0.64, ...
        'seal_leak_fraction',0.0,'inlet_area_factor',1.0,'fault_cylinder',1))];

def.groups = struct( ...
    'G',"load, update, simulate and complete physical Timeseries contract", ...
    'A',"nominal speed, pressure and delivered-flow accuracy", ...
    'Q',"outlet pressure/flow pulsation and three-cylinder balance", ...
    'M',"triplex phase, displacement, check-valve causality and power-path consistency", ...
    'R',"worst declared speed, pressure, leak and inlet-restriction operating point", ...
    'D',"speed-step recovery and paired physical-fault response", ...
    'weights',struct('A',.15,'Q',.15,'M',.30,'R',.20,'D',.20));
end

function s = pin(name, nominal, minv, maxv, unit, meaning)
s = struct('name',name,'nominal',nominal,'min',minv,'max',maxv, ...
    'unit',unit,'meaning',meaning);
end
function s = pout(name, channels, source, unit)
s = struct('name',name,'channels',channels,'unit',unit, ...
    'physical_source',source);
end
function s = scenario(id, values)
s = struct('id',id,'values',values);
end
